/* From Uiverse.io by adamgiebl - Tags: icon, animation, button, send, fly */
.__UIV_SCOPE__ button {
  font-family: inherit;
  font-size: 20px;
  background: royalblue;
  color: white;
  padding: 0.7em 1em;
  padding-left: 0.9em;
  display: flex;
  align-items: center;
  border: none;
  border-radius: 16px;
  overflow: hidden;
  transition: all 0.2s;
}

.__UIV_SCOPE__ button span {
  display: block;
  margin-left: 0.3em;
  transition: all 0.3s ease-in-out;
}

.__UIV_SCOPE__ button svg {
  display: block;
  transform-origin: center center;
  transition: transform 0.3s ease-in-out;
}

.__UIV_SCOPE__ button:hover .svg-wrapper {
  animation: fly-1 0.6s ease-in-out infinite alternate;
}

.__UIV_SCOPE__ button:hover svg {
  transform: translateX(1.2em) rotate(45deg) scale(1.1);
}

.__UIV_SCOPE__ button:hover span {
  transform: translateX(5em);
}

.__UIV_SCOPE__ button:active {
  transform: scale(0.95);
}

@keyframes fly-1 {
  from {
    transform: translateY(0.1em);
  }

  to {
    transform: translateY(-0.1em);
  }
}
